const masterLog = global.get("masterLog") || [];
const newEntries = msg.payload;

global.set("masterLog", masterLog.concat(newEntries));

msg.payload = newEntries;

return msg;

const masterLog = global.get("masterLog") || [];
const existingIds = new Set(masterLog.map(entry => entry.id));

const duplicates = msg.payload.filter(entry => existingIds.has(entry.id));
msg.payload = msg.payload.filter(entry => !existingIds.has(entry.id));

if (duplicates.length > 0) {
    node.warn({ msg: "Duplicate entries removed", duplicates: duplicates });
}

return msg;

const entries = msg.payload;

if (entries.length > 0) {
    const newestEntry = entries.reduce((a, b) => a.timeCreated > b.timeCreated ? a : b); // find newest log entry
    const clientCapitalized = newestEntry.client.charAt(0).toUpperCase() + newestEntry.client.slice(1); // extract client

    global.set(`last${clientCapitalized}EntryTimeStamp`, newestEntry.timeCreated); // update global timestamp variable
}

return msg;
